// METAFORGE-BGREMOVER v1 - helpers: validation, image header parsing, PNG inspection, naming, formatting.
// Generated by install-background-remover.ps1. Safe to edit; re-running the installer backs this file up first.

export const ACCEPTED_EXTENSIONS: readonly string[] = [".jpg", ".jpeg", ".png", ".webp"];
export const ACCEPTED_MIME_TYPES: readonly string[] = ["image/jpeg", "image/png", "image/webp"];
export const ACCEPT_ATTRIBUTE = ".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp";

/**
 * Limits chosen to keep browser memory bounded. A 16 MP RGBA bitmap is about 64 MB, and the engine
 * needs several working copies, so these are deliberately conservative. Raise them only after testing.
 */
export const LIMITS = {
  maxFiles: 25,
  maxFileBytes: 12 * 1024 * 1024,
  maxPixels: 16000000,
  maxSide: 8000,
} as const;

export type SniffedType = "jpeg" | "png" | "webp";

export type ValidationResult =
  | { ok: true; width: number; height: number; type: SniffedType }
  | { ok: false; reason: string };

export interface PngInfo {
  validSignature: boolean;
  width: number;
  height: number;
  colorType: number;
  hasAlphaChannel: boolean;
}

export interface AlphaStats {
  /** Percent of sampled pixels that are fully transparent (alpha = 0). */
  transparentPct: number;
  /** Percent of sampled pixels that are partially transparent (0 < alpha < 255). */
  partialPct: number;
}

function ascii(bytes: Uint8Array, start: number, end: number): string {
  let out = "";
  for (let i = start; i < end && i < bytes.length; i++) out += String.fromCharCode(bytes[i]);
  return out;
}

export function getExtension(name: string): string {
  const dot = name.lastIndexOf(".");
  return dot >= 0 ? name.slice(dot).toLowerCase() : "";
}

export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 0) return "-";
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB"];
  let value = bytes / 1024;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit++;
  }
  return `${value.toFixed(value >= 100 ? 0 : 1)} ${units[unit]}`;
}

export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return "-";
  if (ms < 1000) return `${Math.round(ms)} ms`;
  return `${(ms / 1000).toFixed(1)} s`;
}

export function makeId(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  return `id-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}

/** Identify the real file type from magic bytes. The client-provided MIME type is never trusted alone. */
export async function sniffImageType(file: Blob): Promise<SniffedType | null> {
  const head = new Uint8Array(await file.slice(0, 12).arrayBuffer());
  if (head.length >= 3 && head[0] === 0xff && head[1] === 0xd8 && head[2] === 0xff) return "jpeg";
  if (
    head.length >= 8 &&
    head[0] === 0x89 &&
    head[1] === 0x50 &&
    head[2] === 0x4e &&
    head[3] === 0x47 &&
    head[4] === 0x0d &&
    head[5] === 0x0a &&
    head[6] === 0x1a &&
    head[7] === 0x0a
  ) {
    return "png";
  }
  if (head.length >= 12 && ascii(head, 0, 4) === "RIFF" && ascii(head, 8, 12) === "WEBP") return "webp";
  return null;
}

function jpegSize(b: Uint8Array): { width: number; height: number } | null {
  let i = 2;
  while (i + 9 < b.length) {
    if (b[i] !== 0xff) {
      i++;
      continue;
    }
    const marker = b[i + 1];
    if (marker === 0xff) {
      i++;
      continue;
    }
    if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
      i += 2;
      continue;
    }
    const length = (b[i + 2] << 8) | b[i + 3];
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      return { height: (b[i + 5] << 8) | b[i + 6], width: (b[i + 7] << 8) | b[i + 8] };
    }
    if (length < 2) return null;
    i += 2 + length;
  }
  return null;
}

function webpSize(b: Uint8Array): { width: number; height: number } | null {
  if (b.length < 30) return null;
  const chunk = ascii(b, 12, 16);
  if (chunk === "VP8X") {
    return {
      width: 1 + (b[24] | (b[25] << 8) | (b[26] << 16)),
      height: 1 + (b[27] | (b[28] << 8) | (b[29] << 16)),
    };
  }
  if (chunk === "VP8 ") {
    return {
      width: (b[26] | (b[27] << 8)) & 0x3fff,
      height: (b[28] | (b[29] << 8)) & 0x3fff,
    };
  }
  if (chunk === "VP8L") {
    const bits = (b[21] | (b[22] << 8) | (b[23] << 16) | (b[24] << 24)) >>> 0;
    return { width: (bits & 0x3fff) + 1, height: ((bits >>> 14) & 0x3fff) + 1 };
  }
  return null;
}

/**
 * Read pixel dimensions from the file header WITHOUT decoding the image, so oversized images are
 * rejected before the browser allocates memory for them.
 */
export async function readHeaderSize(
  file: Blob,
  type: SniffedType,
): Promise<{ width: number; height: number } | null> {
  if (type === "png") {
    const b = new Uint8Array(await file.slice(0, 32).arrayBuffer());
    if (b.length < 24) return null;
    const view = new DataView(b.buffer, b.byteOffset, b.byteLength);
    return { width: view.getUint32(16), height: view.getUint32(20) };
  }
  if (type === "webp") {
    const b = new Uint8Array(await file.slice(0, 40).arrayBuffer());
    return webpSize(b);
  }
  const b = new Uint8Array(await file.arrayBuffer());
  return jpegSize(b);
}

/** Decode once to confirm the browser can read the image and to get the display (EXIF-aware) size. */
export async function readImageSize(file: Blob): Promise<{ width: number; height: number }> {
  if (typeof createImageBitmap === "function") {
    const bitmap = await createImageBitmap(file);
    const size = { width: bitmap.width, height: bitmap.height };
    bitmap.close();
    return size;
  }
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve({ width: img.naturalWidth, height: img.naturalHeight });
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("decode failed"));
    };
    img.src = url;
  });
}

export async function validateImageFile(file: File): Promise<ValidationResult> {
  if (file.size === 0) return { ok: false, reason: "The file is empty." };
  if (file.size > LIMITS.maxFileBytes) {
    return {
      ok: false,
      reason: `The file is ${formatBytes(file.size)}; the limit is ${formatBytes(LIMITS.maxFileBytes)} per image.`,
    };
  }
  if (!ACCEPTED_EXTENSIONS.includes(getExtension(file.name)) && !ACCEPTED_MIME_TYPES.includes(file.type)) {
    return { ok: false, reason: "Unsupported format. Use JPG, JPEG, PNG or WEBP." };
  }

  let type: SniffedType | null;
  try {
    type = await sniffImageType(file);
  } catch {
    return { ok: false, reason: "The file could not be read." };
  }
  if (!type) {
    return {
      ok: false,
      reason: "The file contents are not a JPEG, PNG or WEBP image (the extension or type does not match).",
    };
  }

  let header: { width: number; height: number } | null;
  try {
    header = await readHeaderSize(file, type);
  } catch {
    return { ok: false, reason: "The file could not be read." };
  }
  if (!header || header.width < 1 || header.height < 1) {
    return { ok: false, reason: "The image header could not be read; the file may be corrupt." };
  }
  if (header.width * header.height > LIMITS.maxPixels) {
    const mp = (header.width * header.height) / 1000000;
    return {
      ok: false,
      reason: `The image is ${header.width} x ${header.height} px (${mp.toFixed(1)} MP); the limit is ${(LIMITS.maxPixels / 1000000).toFixed(0)} MP. Resize it first.`,
    };
  }
  if (Math.max(header.width, header.height) > LIMITS.maxSide) {
    return {
      ok: false,
      reason: `The longest side is ${Math.max(header.width, header.height)} px; the limit is ${LIMITS.maxSide} px.`,
    };
  }

  try {
    const size = await readImageSize(file);
    return { ok: true, width: size.width, height: size.height, type };
  } catch {
    return { ok: false, reason: "The browser could not decode this image; the file may be corrupt." };
  }
}

/** Check the PNG signature and IHDR so we know the output is a real PNG and whether it has an alpha channel. */
export async function inspectPng(blob: Blob): Promise<PngInfo> {
  const head = new Uint8Array(await blob.slice(0, 33).arrayBuffer());
  const signature = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  const valid =
    head.length >= 33 && signature.every((value, index) => head[index] === value) && ascii(head, 12, 16) === "IHDR";
  if (!valid) {
    return { validSignature: false, width: 0, height: 0, colorType: -1, hasAlphaChannel: false };
  }
  const view = new DataView(head.buffer, head.byteOffset, head.byteLength);
  const colorType = head[25];
  return {
    validSignature: true,
    width: view.getUint32(16),
    height: view.getUint32(20),
    colorType,
    // PNG color types 4 (gray + alpha) and 6 (RGBA) carry a real alpha channel.
    hasAlphaChannel: colorType === 4 || colorType === 6,
  };
}

/**
 * Decode the result into a small canvas and count transparent pixels. This is a real measurement of the
 * exported PNG, not of any CSS preview. It samples at most 256 px on the long side.
 */
export async function measureAlpha(blob: Blob): Promise<AlphaStats> {
  const bitmap = await createImageBitmap(blob, { premultiplyAlpha: "none" });
  try {
    const scale = Math.min(1, 256 / Math.max(bitmap.width, bitmap.height));
    const width = Math.max(1, Math.round(bitmap.width * scale));
    const height = Math.max(1, Math.round(bitmap.height * scale));
    const canvas = document.createElement("canvas");
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext("2d", { willReadFrequently: true });
    if (!ctx) throw new Error("Canvas 2D context is unavailable.");
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(bitmap, 0, 0, width, height);
    const data = ctx.getImageData(0, 0, width, height).data;
    let transparent = 0;
    let partial = 0;
    for (let i = 3; i < data.length; i += 4) {
      const alpha = data[i];
      if (alpha === 0) transparent++;
      else if (alpha < 255) partial++;
    }
    const total = width * height;
    return { transparentPct: (transparent / total) * 100, partialPct: (partial / total) * 100 };
  } finally {
    bitmap.close();
  }
}

const RESERVED_WINDOWS_NAMES = /^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/i;

/** Filesystem-safe base name (no extension) derived from the original filename. */
export function safeBaseName(originalName: string): string {
  const dot = originalName.lastIndexOf(".");
  const base = dot > 0 ? originalName.slice(0, dot) : originalName;
  let name = base
    .replace(/[<>:"\/\\|?*\u0000-\u001f]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^[.\-\s]+|[.\-\s]+$/g, "");
  if (name.length > 80) name = name.slice(0, 80).replace(/[.\-\s]+$/g, "");
  if (!name || RESERVED_WINDOWS_NAMES.test(name)) name = name ? `${name}-image` : "image";
  return name;
}

export function outputFileName(originalName: string): string {
  return `${safeBaseName(originalName)}-transparent.png`;
}

/** Make a name unique inside one ZIP, case-insensitively, by appending -2, -3, ... */
export function uniqueName(fileName: string, used: Set<string>): string {
  const dot = fileName.lastIndexOf(".");
  const stem = dot > 0 ? fileName.slice(0, dot) : fileName;
  const ext = dot > 0 ? fileName.slice(dot) : "";
  let candidate = fileName;
  let counter = 2;
  while (used.has(candidate.toLowerCase())) {
    candidate = `${stem}-${counter}${ext}`;
    counter++;
  }
  used.add(candidate.toLowerCase());
  return candidate;
}

/** Turn an engine/browser error into a message that says what happened and what to try. */
export function describeError(err: unknown): string {
  const raw = err instanceof Error ? err.message : typeof err === "string" ? err : "Unknown error";
  const lower = raw.toLowerCase();
  if (lower.includes("failed to fetch") || lower.includes("networkerror") || lower.includes("load failed")) {
    return `Model files could not be downloaded. Check your internet connection and any ad blocker or firewall, then retry. (${raw})`;
  }
  if (lower.includes("memory") || lower.includes("alloc")) {
    return `A memory error occurred in the browser. Close other tabs, try the Fast model or a smaller image, then retry. (${raw})`;
  }
  if (lower.includes("webassembly") || lower.includes("wasm")) {
    return `WebAssembly failed to run in this browser. Use a current version of Chrome, Edge or Firefox. (${raw})`;
  }
  return raw;
}